WITH 
CANDIDATE_SK AS 
( 
    SELECT DISTINCT
          SAT_SRC1_1_1.KIMBLEONE__FIRSTNAME__C                       AS FIRST_NAME 
        , SAT_SRC1_1_1.KIMBLEONE__LASTNAME__C                        AS LAST_NAME 
        , SAT_SRC1_1_1.KIMBLEONE__STARTDATE__C                       AS START_DATE 
        , SAT_SRC1_1_1.KIMBLEONE__ENDDATE__C                         AS END_DATE
        , SAT_SRC1_1_1.KIMBLEONE__STANDARDCOST__C                    AS STANDARD_COST 
        , SAT_SRC1_1_1.KIMBLEONE__STANDARDREVENUE__C                 AS STANDARD_REVENUE 
        , SAT_SRC1_1_1.KIMBLEONE__LOCATION__C                        AS LOCATION
        , SAT_SRC1_1_1.KIMBLEONE__LATESTP1ASSIGNMENTENDDATE__C       AS ASSIGNED_UNTIL
        , SAT_SRC1_1_1.KC_ADP_CO_CODE__C                             AS ADP_CO_CODE
        , SAT_SRC1_1_1.KC_INTACCT_VENDOR_ID__C                       AS INTACT_VENDOR_ID
        , SAT_SRC1_1_1.KC_NON_EXEMPT__C                              AS NON_EXEMPT
        , SAT_SRC1_1_1.KIMBLEONE__ISACTUALUNTRACKED__C               AS ACTUAL_UNTRACKED
        , DVO_SRC1.CANDIDATE_HKEY                                    AS BASE_OBJECT_H_KEY
        , DVO_SRC1.CANDIDATE_BK                                      AS CANDIDATE_SK_BK
        , SAT_SRC1_1_1._AIRBYTE_EXTRACTED_AT                         AS SNAPSHOT__TIMESTAMP
        , SAT_SRC1_1_1.NAME                                          AS CANDIDATE_SK_NAME
    FROM {{ source('eli_dv_bv', 'hub_candidate') }} DVO_SRC1
    JOIN {{ ref('sat_sk_candidate_bvv_curr') }} SAT_SRC1_1_1
      ON DVO_SRC1.CANDIDATE_HKEY = SAT_SRC1_1_1.CANDIDATE_HKEY
)   
, CANDIDATE_SF AS
( 
    SELECT DISTINCT
          DVO_SRC2.CANDIDATE_HKEY              AS BASE_OBJECT_H_KEY
        , DVO_SRC2.CANDIDATE_BK                AS CANDIDATE_SF_BK
        , SAT_SRC1_1_2._AIRBYTE_EXTRACTED_AT       AS SNAPSHOT__TIMESTAMP
        , SAT_SRC1_1_2.CANDIDATE_FULL_NAME         AS CANDIDATE_SF_NAME
        , SAT_SRC1_1_2.MAIN_STREET               AS STREET
        , SAT_SRC1_1_2.MAIN_CITY                AS CITY
        , SAT_SRC1_1_2.MAIN_STATE               AS STATE
        , SAT_SRC1_1_2.MAIN_COUNTRY             AS COUNTRY
        , SAT_SRC1_1_2.MAIN_POSTAL_CODE         AS POSTAL_CODE
    FROM {{ source('eli_dv_bv', 'hub_candidate') }} DVO_SRC2
    JOIN {{ ref('sat_ssc_candidate_bvv_curr') }} SAT_SRC1_1_2
      ON DVO_SRC2.CANDIDATE_HKEY = SAT_SRC1_1_2.CANDIDATE_HKEY
)
, COMPANY AS
(
    SELECT DISTINCT 
          DVO_SRC3.COMPANY_HKEY           AS BASE_OBJECT_H_KEY
        , DVO_SRC3.COMPANY_BK             AS COMPANY_BK
        , SAT_SRC1_1_3._AIRBYTE_EXTRACTED_AT  AS SNAPSHOT__TIMESTAMP
        , SAT_SRC1_1_3.ACCOUNT_NAME           AS SUPPLIER
    FROM {{ source('eli_dv_bv', 'hub_company') }} DVO_SRC3
    JOIN {{ ref('sat_ssc_company_bvv_curr') }} SAT_SRC1_1_3
      ON DVO_SRC3.COMPANY_HKEY = SAT_SRC1_1_3.COMPANY_HKEY    
)
, RESOURCETYPE AS
(
    SELECT DISTINCT 
          DVO_SRC4.KIMBLEONE__RESOURCETYPE__C_HKEY AS BASE_OBJECT_H_KEY
        , DVO_SRC4.ID_BK                           AS RESOURCETYPE_BK
        , SAT_SRC1_1_4._AIRBYTE_EXTRACTED_AT           AS SNAPSHOT__TIMESTAMP
        , SAT_SRC1_1_4.NAME                            AS RESOURCE_TYPE
    FROM {{ source('eli_dv_bv', 'hub_kimbleone__resourcetype__c') }} DVO_SRC4
    JOIN {{ ref('sat_sk_kimbleone__resourcetype__c_bvv_curr') }} SAT_SRC1_1_4
      ON DVO_SRC4.KIMBLEONE__RESOURCETYPE__C_HKEY = SAT_SRC1_1_4.KIMBLEONE__RESOURCETYPE__C_HKEY      
)
, CANDIDATE_MANAGER AS
(
    SELECT DISTINCT 
          DVO_SRC5.CANDIDATE_HKEY          AS BASE_OBJECT_H_KEY
        , DVO_SRC5.CANDIDATE_BK            AS CANDIDATE_MANAGER_BK
        , SAT_SRC1_1_5._AIRBYTE_EXTRACTED_AT   AS SNAPSHOT__TIMESTAMP
        , SAT_SRC1_1_5.NAME     AS MANAGER
    FROM {{ source('eli_dv_bv', 'hub_candidate') }} DVO_SRC5
    JOIN {{ ref('sat_sk_candidate_bvv_curr') }} SAT_SRC1_1_5
      ON DVO_SRC5.CANDIDATE_HKEY = SAT_SRC1_1_5.CANDIDATE_HKEY     
)
, USERS AS
(
    SELECT DISTINCT
          DVO_SRC6.USER_HKEY               AS BASE_OBJECT_H_KEY
        , DVO_SRC6.USER_BK                 AS USER_BK
        , SAT_SRC1_1_6._AIRBYTE_EXTRACTED_AT   AS SNAPSHOT__TIMESTAMP
        , SAT_SRC1_1_6.NAME                    AS USER_NAME
    FROM {{ source('eli_dv_bv', 'hub_user') }} DVO_SRC6
    JOIN {{ ref('sat_ssc_user_bvv_curr') }} SAT_SRC1_1_6
      ON DVO_SRC6.USER_HKEY = SAT_SRC1_1_6.USER_HKEY    
)
, RESOURCE_HISTORY AS
(
    SELECT DISTINCT
          DVO_SRC7.KIMBLEONE__RESOURCEHISTORY__C_HKEY AS BASE_OBJECT_H_KEY
        , DVO_SRC7.ID_BK                              AS RESOURCEHISTORY_BK
        , SAT_SRC1_1_7._AIRBYTE_EXTRACTED_AT              AS SNAPSHOT__TIMESTAMP
    FROM {{ source('eli_dv_bv', 'hub_kimbleone__resourcehistory__c') }} DVO_SRC7
    JOIN {{ ref('sat_sk_kimbleone__resourcehistory__c_bvv_curr') }} SAT_SRC1_1_7
      ON DVO_SRC7.KIMBLEONE__RESOURCEHISTORY__C_HKEY = SAT_SRC1_1_7.KIMBLEONE__RESOURCEHISTORY__C_HKEY    
)
, BUSINESSUNIT AS
(
    SELECT DISTINCT
          DVO_SRC8.KIMBLEONE__BUSINESSUNIT__C_HKEY AS BASE_OBJECT_H_KEY
        , DVO_SRC8.ID_BK                            AS BUSINESSUNIT_BK
        , SAT_SRC1_1_8._AIRBYTE_EXTRACTED_AT            AS SNAPSHOT__TIMESTAMP
        , SAT_SRC1_1_8.NAME                             AS BUSINESSUNIT_NAME
    FROM {{ source('eli_dv_bv', 'hub_kimbleone__businessunit__c') }} DVO_SRC8
    JOIN {{ ref('sat_sk_kimbleone__businessunit__c_bvv_curr') }} SAT_SRC1_1_8
      ON DVO_SRC8.KIMBLEONE__BUSINESSUNIT__C_HKEY = SAT_SRC1_1_8.KIMBLEONE__BUSINESSUNIT__C_HKEY    
)
, BUSINESSUNIT_PARENT AS
(
    SELECT DISTINCT
          DVO_SRC9.KIMBLEONE__BUSINESSUNIT__C_HKEY AS BASE_OBJECT_H_KEY
        , DVO_SRC9.ID_BK                           AS BUSINESSUNIT_PARENT_BK
        , SAT_SRC1_1_9._AIRBYTE_EXTRACTED_AT           AS SNAPSHOT__TIMESTAMP
        , SAT_SRC1_1_9.NAME                            AS BUSINESSUNIT_PARENT_NAME
    FROM {{ source('eli_dv_bv', 'hub_kimbleone__businessunit__c') }} DVO_SRC9
    JOIN {{ ref('sat_sk_kimbleone__businessunit__c_bvv_curr') }} SAT_SRC1_1_9
      ON DVO_SRC9.KIMBLEONE__BUSINESSUNIT__C_HKEY = SAT_SRC1_1_9.KIMBLEONE__BUSINESSUNIT__C_HKEY    
)
, BUSINESSUNIT_GRAND_PARENT AS
(
    SELECT DISTINCT
          DVO_SRC9_1.KIMBLEONE__BUSINESSUNIT__C_HKEY AS BASE_OBJECT_H_KEY
        , DVO_SRC9_1.ID_BK                           AS BUSINESSUNIT_GRAND_PARENT_BK
        , SAT_SRC1_1_9_1._AIRBYTE_EXTRACTED_AT           AS SNAPSHOT__TIMESTAMP
        , SAT_SRC1_1_9_1.NAME                            AS BUSINESSUNIT_GRAND_PARENT_NAME
    FROM {{ source('eli_dv_bv', 'hub_kimbleone__businessunit__c') }} DVO_SRC9_1
    JOIN {{ ref('sat_sk_kimbleone__businessunit__c_bvv_curr') }} SAT_SRC1_1_9_1
      ON DVO_SRC9_1.KIMBLEONE__BUSINESSUNIT__C_HKEY = SAT_SRC1_1_9_1.KIMBLEONE__BUSINESSUNIT__C_HKEY    
)
, CANDIDATE_SK_LNK_CANDIDATE_SF AS
(
    SELECT DISTINCT 
          DVO_SRC10.CANDIDATE_HKEY                                 AS BASE_OBJECT_H_KEY
        , DVO_SRC10.LNA_CANDIDATE_CANDIDATE_KIMBLEONECONTACTC_HKEY AS BASE_OBJECT_L_H_KEY
        , DVO_SRC10.CANDIDATE_KIMBLEONECONTACTC_HKEY               AS BASE_OBJECT_F_H_KEY
        , ROW_NUMBER() OVER (
            PARTITION BY DVO_SRC10.CANDIDATE_HKEY 
            ORDER BY SAT_SRC1_1_10._AIRBYTE_EXTRACTED_AT DESC
          )                                                             AS RN
        , SAT_SRC1_1_10._AIRBYTE_EXTRACTED_AT                           AS SNAPSHOT__TIMESTAMP
    FROM {{ source('eli_dv_bv', 'view_lna_candidate_candidate_kimbleonecontactc') }} DVO_SRC10
    JOIN {{ ref('view_las_sk_candidate_candidate_kimbleonecontactc_bvv_curr') }} SAT_SRC1_1_10
      ON DVO_SRC10.LNA_CANDIDATE_CANDIDATE_KIMBLEONECONTACTC_HKEY = SAT_SRC1_1_10.LNA_CANDIDATE_CANDIDATE_KIMBLEONECONTACTC_HKEY         
)
, CANDIDATE_SF_LNK_COMPANY AS
(
    SELECT DISTINCT 
          DVO_SRC11.CANDIDATE_HKEY                  AS BASE_OBJECT_H_KEY
        , DVO_SRC11.LNK_CANDIDATE_COMPANY_HKEY      AS BASE_OBJECT_L_H_KEY
        , DVO_SRC11.COMPANY_HKEY                    AS BASE_OBJECT_F_H_KEY
        , ROW_NUMBER() OVER (
            PARTITION BY DVO_SRC11.CANDIDATE_HKEY 
            ORDER BY SAT_SRC1_1_11._AIRBYTE_EXTRACTED_AT DESC
          )                                              AS RN
        , SAT_SRC1_1_11._AIRBYTE_EXTRACTED_AT           AS SNAPSHOT__TIMESTAMP
    FROM {{ source('eli_dv_bv', 'lnk_candidate_company') }} DVO_SRC11
    JOIN {{ ref('lks_ssc_candidate_company_bvv_curr') }} SAT_SRC1_1_11
      ON DVO_SRC11.LNK_CANDIDATE_COMPANY_HKEY = SAT_SRC1_1_11.LNK_CANDIDATE_COMPANY_HKEY    
)
, CANDIDATE_SK_LNK_RESOURCETYPE AS
(
    SELECT DISTINCT 
          DVO_SRC12.CANDIDATE_HKEY                            AS BASE_OBJECT_H_KEY
        , DVO_SRC12.LNK_CANDIDATE_KIMBLEONERESOURCETYPEC_HKEY AS BASE_OBJECT_L_H_KEY
        , DVO_SRC12.KIMBLEONE__RESOURCETYPE__C_HKEY           AS BASE_OBJECT_F_H_KEY
        , ROW_NUMBER() OVER (
            PARTITION BY DVO_SRC12.CANDIDATE_HKEY 
            ORDER BY SAT_SRC1_1_12._AIRBYTE_EXTRACTED_AT DESC
          )                                                        AS RN
        , SAT_SRC1_1_12._AIRBYTE_EXTRACTED_AT                      AS SNAPSHOT__TIMESTAMP
    FROM {{ source('eli_dv_bv', 'lnk_candidate_kimbleoneresourcetypec') }} DVO_SRC12
    JOIN {{ ref('lks_sk_candidate_kimbleoneresourcetypec_bvv_curr') }} SAT_SRC1_1_12
      ON DVO_SRC12.LNK_CANDIDATE_KIMBLEONERESOURCETYPEC_HKEY = SAT_SRC1_1_12.LNK_CANDIDATE_KIMBLEONERESOURCETYPEC_HKEY    
)
, CANDIDATE_SK_LNK_CANDIDATE_MANAGER AS
(
    SELECT DISTINCT 
          DVO_SRC13.CANDIDATE_HKEY                                              AS BASE_OBJECT_H_KEY
        , DVO_SRC13.LNK_CANDIDATE_CANDIDATE_KIMBLEONERESOURCEMANAGERC_HKEY      AS BASE_OBJECT_L_H_KEY
        , DVO_SRC13.CANDIDATE_KIMBLEONERESOURCEMANAGERC_HKEY                    AS BASE_OBJECT_F_H_KEY
        , ROW_NUMBER() OVER (
            PARTITION BY DVO_SRC13.CANDIDATE_HKEY 
            ORDER BY SAT_SRC1_1_13._AIRBYTE_EXTRACTED_AT DESC
          )                                                                     AS RN
        , SAT_SRC1_1_13._AIRBYTE_EXTRACTED_AT                                   AS SNAPSHOT__TIMESTAMP
    FROM {{ source('eli_dv_bv', 'lnk_candidate_candidate_kimbleoneresourcemanagerc') }} DVO_SRC13
    JOIN {{ ref('lks_sk_candidate_candidate_kimbleoneresourcemanagerc_bvv_curr') }} SAT_SRC1_1_13
      ON DVO_SRC13.LNK_CANDIDATE_CANDIDATE_KIMBLEONERESOURCEMANAGERC_HKEY = SAT_SRC1_1_13.LNK_CANDIDATE_CANDIDATE_KIMBLEONERESOURCEMANAGERC_HKEY    
)
, CANDIDATE_SK_LNK_USER AS
(
    SELECT DISTINCT 
          DVO_SRC14.CANDIDATE_HKEY           AS BASE_OBJECT_H_KEY
        , DVO_SRC14.LNA_CANDIDATE_USER_HKEY  AS BASE_OBJECT_L_H_KEY
        , DVO_SRC14.USER_HKEY                AS BASE_OBJECT_F_H_KEY
        , ROW_NUMBER() OVER (
            PARTITION BY DVO_SRC14.CANDIDATE_HKEY 
            ORDER BY SAT_SRC1_1_14._AIRBYTE_EXTRACTED_AT DESC
          )                                       AS RN
        , SAT_SRC1_1_14._AIRBYTE_EXTRACTED_AT     AS SNAPSHOT__TIMESTAMP
    FROM {{ source('eli_dv_bv', 'view_lna_candidate_user') }} DVO_SRC14
    JOIN {{ ref('view_las_sk_candidate_user_bvv_curr') }} SAT_SRC1_1_14
      ON DVO_SRC14.LNA_CANDIDATE_USER_HKEY = SAT_SRC1_1_14.LNA_CANDIDATE_USER_HKEY    
)
, CANDIDATE_SK_LNK_RESOURCEHISTORY AS
(
    SELECT DISTINCT 
          DVO_SRC15.CANDIDATE_HKEY                               AS BASE_OBJECT_H_KEY
        , DVO_SRC15.LNK_KIMBLEONERESOURCEHISTORYC_CANDIDATE_HKEY AS BASE_OBJECT_L_H_KEY
        , DVO_SRC15.KIMBLEONE__RESOURCEHISTORY__C_HKEY           AS BASE_OBJECT_F_H_KEY
        , ROW_NUMBER() OVER (
            PARTITION BY DVO_SRC15.CANDIDATE_HKEY 
            ORDER BY SAT_SRC1_1_15._AIRBYTE_EXTRACTED_AT DESC
          )                                                           AS RN
        , SAT_SRC1_1_15._AIRBYTE_EXTRACTED_AT                         AS SNAPSHOT__TIMESTAMP
    FROM {{ source('eli_dv_bv', 'lnk_kimbleoneresourcehistoryc_candidate') }} DVO_SRC15
    JOIN {{ ref('lks_sk_kimbleoneresourcehistoryc_candidate_bvv_curr') }} SAT_SRC1_1_15
      ON DVO_SRC15.LNK_KIMBLEONERESOURCEHISTORYC_CANDIDATE_HKEY = SAT_SRC1_1_15.LNK_KIMBLEONERESOURCEHISTORYC_CANDIDATE_HKEY    
)
,  RESOURCEHISTORY_LNK_BUSINESSUNIT AS
(
    SELECT DISTINCT 
          DVO_SRC16.KIMBLEONE__RESOURCEHISTORY__C_HKEY                             AS BASE_OBJECT_H_KEY
        , DVO_SRC16.LNK_KIMBLEONERESOURCEHISTORYC_KIMBLEONEBUSINESSUNITC_HKEY      AS BASE_OBJECT_L_H_KEY
        , DVO_SRC16.KIMBLEONE__BUSINESSUNIT__C_HKEY                                AS BASE_OBJECT_F_H_KEY
        , ROW_NUMBER() OVER (
            PARTITION BY DVO_SRC16.KIMBLEONE__RESOURCEHISTORY__C_HKEY 
            ORDER BY SAT_SRC1_1_16._AIRBYTE_EXTRACTED_AT DESC
          )                                                                             AS RN
        , SAT_SRC1_1_16._AIRBYTE_EXTRACTED_AT                                           AS SNAPSHOT__TIMESTAMP
    FROM {{ source('eli_dv_bv', 'lnk_kimbleoneresourcehistoryc_kimbleonebusinessunitc') }} DVO_SRC16
    JOIN {{ ref('lks_sk_kimbleoneresourcehistoryc_kimbleonebusinessunitc_bvv_curr') }} SAT_SRC1_1_16
      ON DVO_SRC16.LNK_KIMBLEONERESOURCEHISTORYC_KIMBLEONEBUSINESSUNITC_HKEY = SAT_SRC1_1_16.LNK_KIMBLEONERESOURCEHISTORYC_KIMBLEONEBUSINESSUNITC_HKEY 
)
, BUSINESSUNIT_LNK_BUSINESSUNIT_PARENT AS
(
    SELECT DISTINCT 
          DVO_SRC17.KIMBLEONE__BUSINESSUNIT__C_HKEY                                        AS BASE_OBJECT_H_KEY
        , DVO_SRC17.LNK_KIMBLEONEBUSINESSUNITC_KIMBLEONEBUSINESSUNITC_KIMBLEONEBUSINESSUNITC_HKEY AS BASE_OBJECT_L_H_KEY
        , DVO_SRC17.KIMBLEONE__BUSINESSUNIT__C_KIMBLEONEBUSINESSUNITC_HKEY                 AS BASE_OBJECT_F_H_KEY
        , ROW_NUMBER() OVER (
            PARTITION BY DVO_SRC17.KIMBLEONE__BUSINESSUNIT__C_HKEY 
            ORDER BY SAT_SRC1_1_17._AIRBYTE_EXTRACTED_AT DESC
          )                                                                                      AS RN
        , SAT_SRC1_1_17._AIRBYTE_EXTRACTED_AT                                                    AS SNAPSHOT__TIMESTAMP
    FROM {{ source('eli_dv_bv', 'lnk_kimbleonebusinessunitc_kimbleonebusinessunitc_kimbleonebusinessunitc') }} DVO_SRC17
    JOIN {{ ref('lks_sk_kimbleonebusinessunitc_kimbleonebusinessunitc_kimbleonebusinessunitc_bvv_curr') }} SAT_SRC1_1_17
      ON DVO_SRC17.LNK_KIMBLEONEBUSINESSUNITC_KIMBLEONEBUSINESSUNITC_KIMBLEONEBUSINESSUNITC_HKEY = SAT_SRC1_1_17.LNK_KIMBLEONEBUSINESSUNITC_KIMBLEONEBUSINESSUNITC_KIMBLEONEBUSINESSUNITC_HKEY 
)
, BUSINESSUNIT_PARENT_LNK_BUSINESSUNIT_GRAND_PARENT AS
(
    SELECT DISTINCT 
          DVO_SRC17_1.KIMBLEONE__BUSINESSUNIT__C_HKEY                                        AS BASE_OBJECT_H_KEY
        , DVO_SRC17_1.LNK_KIMBLEONEBUSINESSUNITC_KIMBLEONEBUSINESSUNITC_KIMBLEONEBUSINESSUNITC_HKEY AS BASE_OBJECT_L_H_KEY
        , DVO_SRC17_1.KIMBLEONE__BUSINESSUNIT__C_KIMBLEONEBUSINESSUNITC_HKEY                 AS BASE_OBJECT_F_H_KEY
        , ROW_NUMBER() OVER (
            PARTITION BY DVO_SRC17_1.KIMBLEONE__BUSINESSUNIT__C_HKEY 
            ORDER BY SAT_SRC1_1_17_1._AIRBYTE_EXTRACTED_AT DESC
          )                                                                                      AS RN
        , SAT_SRC1_1_17_1._AIRBYTE_EXTRACTED_AT                                                    AS SNAPSHOT__TIMESTAMP
    FROM {{ source('eli_dv_bv', 'lnk_kimbleonebusinessunitc_kimbleonebusinessunitc_kimbleonebusinessunitc') }} DVO_SRC17_1
    JOIN {{ ref('lks_sk_kimbleonebusinessunitc_kimbleonebusinessunitc_kimbleonebusinessunitc_bvv_curr') }} SAT_SRC1_1_17_1
      ON DVO_SRC17_1.LNK_KIMBLEONEBUSINESSUNITC_KIMBLEONEBUSINESSUNITC_KIMBLEONEBUSINESSUNITC_HKEY = SAT_SRC1_1_17_1.LNK_KIMBLEONEBUSINESSUNITC_KIMBLEONEBUSINESSUNITC_KIMBLEONEBUSINESSUNITC_HKEY 
)
--   FINAL SELECT
SELECT DISTINCT 
      UPPER(SHA2(
        UPPER(REPLACE(COALESCE(TRIM(CANDIDATE_SK.CANDIDATE_SK_BK),'~'), '\#', '\\\#')) || '\#' ||
        UPPER(REPLACE(COALESCE(TRIM(TO_CHAR(CANDIDATE_SK.SNAPSHOT__TIMESTAMP, 'DD/MM/YYYY HH24:MI:SS')),'~'), '\#', '\\\#')) ||          '\#')) AS DIM_CANDIDATE_HKEY
    , CANDIDATE_SK.CANDIDATE_SK_BK 
    , CANDIDATE_SK.CANDIDATE_SK_NAME 
    , CANDIDATE_SK.FIRST_NAME
    , CANDIDATE_SK.LAST_NAME
    , CANDIDATE_SK.START_DATE
    , CANDIDATE_SK.END_DATE
    , CANDIDATE_SK.STANDARD_COST
    , CANDIDATE_SK.STANDARD_REVENUE
    , CANDIDATE_SF.STREET
    , CANDIDATE_SF.CITY
    , CANDIDATE_SF.STATE
    , CANDIDATE_SF.COUNTRY
    , CANDIDATE_SF.POSTAL_CODE
    , CANDIDATE_SK.ASSIGNED_UNTIL
    , CANDIDATE_SK.ADP_CO_CODE
    , CANDIDATE_SK.INTACT_VENDOR_ID
    , CANDIDATE_SK.NON_EXEMPT
    , CANDIDATE_SK.ACTUAL_UNTRACKED
    , CANDIDATE_SF.CANDIDATE_SF_NAME
    , COMPANY.SUPPLIER
    , RESOURCETYPE.RESOURCE_TYPE
	, CANDIDATE_MANAGER.MANAGER
    , USERS.USER_NAME
    , BUSINESSUNIT.BUSINESSUNIT_NAME
    , BUSINESSUNIT_PARENT.BUSINESSUNIT_PARENT_NAME
    , BUSINESSUNIT_GRAND_PARENT.BUSINESSUNIT_GRAND_PARENT_NAME

FROM CANDIDATE_SK
INNER JOIN CANDIDATE_SK_LNK_CANDIDATE_SF
  ON CANDIDATE_SK.BASE_OBJECT_H_KEY = CANDIDATE_SK_LNK_CANDIDATE_SF.BASE_OBJECT_H_KEY
 AND CANDIDATE_SK_LNK_CANDIDATE_SF.RN = 1
 JOIN CANDIDATE_SF
  ON CANDIDATE_SF.BASE_OBJECT_H_KEY = CANDIDATE_SK_LNK_CANDIDATE_SF.BASE_OBJECT_F_H_KEY

 JOIN CANDIDATE_SF_LNK_COMPANY
  ON CANDIDATE_SF.BASE_OBJECT_H_KEY = CANDIDATE_SF_LNK_COMPANY.BASE_OBJECT_H_KEY
 AND CANDIDATE_SF_LNK_COMPANY.RN = 1
 JOIN COMPANY
  ON COMPANY.BASE_OBJECT_H_KEY = CANDIDATE_SF_LNK_COMPANY.BASE_OBJECT_F_H_KEY

 JOIN CANDIDATE_SK_LNK_RESOURCETYPE
  ON CANDIDATE_SK.BASE_OBJECT_H_KEY = CANDIDATE_SK_LNK_RESOURCETYPE.BASE_OBJECT_H_KEY
 AND CANDIDATE_SK_LNK_RESOURCETYPE.RN = 1
 JOIN RESOURCETYPE
  ON RESOURCETYPE.BASE_OBJECT_H_KEY = CANDIDATE_SK_LNK_RESOURCETYPE.BASE_OBJECT_F_H_KEY

 JOIN CANDIDATE_SK_LNK_CANDIDATE_MANAGER
  ON CANDIDATE_SK.BASE_OBJECT_H_KEY = CANDIDATE_SK_LNK_CANDIDATE_MANAGER.BASE_OBJECT_H_KEY
 AND CANDIDATE_SK_LNK_CANDIDATE_MANAGER.RN = 1
 JOIN CANDIDATE_MANAGER
  ON CANDIDATE_MANAGER.BASE_OBJECT_H_KEY = CANDIDATE_SK_LNK_CANDIDATE_MANAGER.BASE_OBJECT_F_H_KEY
  
 JOIN CANDIDATE_SK_LNK_USER
  ON CANDIDATE_SK.BASE_OBJECT_H_KEY = CANDIDATE_SK_LNK_USER.BASE_OBJECT_H_KEY
 AND CANDIDATE_SK_LNK_USER.RN = 1
 JOIN USERS
  ON USERS.BASE_OBJECT_H_KEY = CANDIDATE_SK_LNK_USER.BASE_OBJECT_F_H_KEY

 JOIN CANDIDATE_SK_LNK_RESOURCEHISTORY
  ON CANDIDATE_SK.BASE_OBJECT_H_KEY = CANDIDATE_SK_LNK_RESOURCEHISTORY.BASE_OBJECT_H_KEY
 AND CANDIDATE_SK_LNK_RESOURCEHISTORY.RN = 1
 JOIN RESOURCE_HISTORY RESOURCEHISTORY
  ON RESOURCEHISTORY.BASE_OBJECT_H_KEY = CANDIDATE_SK_LNK_RESOURCEHISTORY.BASE_OBJECT_F_H_KEY
 
  JOIN RESOURCEHISTORY_LNK_BUSINESSUNIT
  ON RESOURCEHISTORY.BASE_OBJECT_H_KEY = RESOURCEHISTORY_LNK_BUSINESSUNIT.BASE_OBJECT_H_KEY
 AND RESOURCEHISTORY_LNK_BUSINESSUNIT.RN = 1 
 JOIN BUSINESSUNIT
  ON BUSINESSUNIT.BASE_OBJECT_H_KEY = RESOURCEHISTORY_LNK_BUSINESSUNIT.BASE_OBJECT_F_H_KEY

 JOIN BUSINESSUNIT_LNK_BUSINESSUNIT_PARENT
  ON BUSINESSUNIT.BASE_OBJECT_H_KEY = BUSINESSUNIT_LNK_BUSINESSUNIT_PARENT.BASE_OBJECT_H_KEY
 AND BUSINESSUNIT_LNK_BUSINESSUNIT_PARENT.RN = 1
 JOIN BUSINESSUNIT_PARENT
  ON BUSINESSUNIT_PARENT.BASE_OBJECT_H_KEY = BUSINESSUNIT_LNK_BUSINESSUNIT_PARENT.BASE_OBJECT_F_H_KEY
  
 JOIN BUSINESSUNIT_PARENT_LNK_BUSINESSUNIT_GRAND_PARENT
  ON BUSINESSUNIT_PARENT.BASE_OBJECT_H_KEY = BUSINESSUNIT_PARENT_LNK_BUSINESSUNIT_GRAND_PARENT.BASE_OBJECT_H_KEY
 AND BUSINESSUNIT_PARENT_LNK_BUSINESSUNIT_GRAND_PARENT.RN = 1
 JOIN BUSINESSUNIT_GRAND_PARENT
  ON BUSINESSUNIT_GRAND_PARENT.BASE_OBJECT_H_KEY = BUSINESSUNIT_PARENT_LNK_BUSINESSUNIT_GRAND_PARENT.BASE_OBJECT_F_H_KEY
